import json
from collections import deque
path='/root/DATA/products/CoachForce.json'
with open(path) as f:
    data=json.load(f)

target='Market Research Report'

# BFS to find paths containing target in string values
paths=[]
queue=deque([(data, '')])
while queue:
    obj, path_str = queue.popleft()
    if isinstance(obj, dict):
        for k,v in obj.items():
            newp=f"{path_str}.{k}" if path_str else k
            if isinstance(v, (dict,list)):
                queue.append((v,newp))
            elif isinstance(v,str) and target in v:
                paths.append((newp,v))
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            newp=f"{path_str}[{i}]"
            if isinstance(v,(dict,list)):
                queue.append((v,newp))
            elif isinstance(v,str) and target in v:
                paths.append((newp,v))
print('found',len(paths))
for p,v in paths[:20]:
    print(p, v[:200])
